#!/usr/bin/env node
// Generate small sample files for browser checks of the 3D / layer viewers:
//   torus.stl   — binary STL torus (~10k triangles)
//   vase.gcode  — a 60-layer twisted vase with travel moves and retractions
const fs = require("fs");
const path = require("path");

function torusStl(R = 25, r = 9, nu = 96, nv = 48) {
  const tris = [];
  const pt = (i, j) => {
    const u = (i / nu) * Math.PI * 2;
    const v = (j / nv) * Math.PI * 2;
    return [(R + r * Math.cos(v)) * Math.cos(u), (R + r * Math.cos(v)) * Math.sin(u), r * Math.sin(v) + r];
  };
  for (let i = 0; i < nu; i++)
    for (let j = 0; j < nv; j++) {
      const a = pt(i, j), b = pt(i + 1, j), c = pt(i + 1, j + 1), d = pt(i, j + 1);
      tris.push([a, b, c], [a, c, d]);
    }
  const buf = Buffer.alloc(84 + tris.length * 50);
  buf.write("print-farm sample torus", 0);
  buf.writeUInt32LE(tris.length, 80);
  tris.forEach((t, k) => {
    const o = 84 + k * 50;
    t.forEach((p, vi) => p.forEach((x, ci) => buf.writeFloatLE(x, o + 12 + vi * 12 + ci * 4)));
  });
  return buf;
}

function vaseGcode(layers = 60, h = 0.3) {
  const out = ["; generated by print-farm make-samples.js", "; total layers count = " + layers, "G21", "G90", "M83", "G28", "G1 Z5 F3000"];
  const cx = 110, cy = 110;
  for (let l = 0; l < layers; l++) {
    const z = +(h * (l + 1)).toFixed(2);
    out.push(";LAYER_CHANGE", ";Z:" + z, `G1 Z${z + 0.4} F900`, `G0 X${cx + 30} Y${cy}`, `G1 Z${z}`, "G1 E0.8 F2400");
    const sides = 6;
    const twist = (l / layers) * Math.PI * 0.6;
    const rad = 22 + 8 * Math.sin((l / layers) * Math.PI);
    for (let s = 1; s <= sides * 8; s++) {
      const a = twist + (s / (sides * 8)) * Math.PI * 2;
      const k = 1 + 0.12 * Math.cos(a * sides);
      out.push(`G1 X${(cx + rad * k * Math.cos(a)).toFixed(3)} Y${(cy + rad * k * Math.sin(a)).toFixed(3)} E0.05 F1800`);
    }
    // inner ring + a travel across
    out.push("G1 E-0.8 F2400", `G0 X${cx + 8} Y${cy}`, "G1 E0.8");
    for (let s = 1; s <= 24; s++) {
      const a = (s / 24) * Math.PI * 2;
      out.push(`G1 X${(cx + 8 * Math.cos(a)).toFixed(3)} Y${(cy + 8 * Math.sin(a)).toFixed(3)} E0.03`);
    }
    out.push("G1 E-0.8");
  }
  out.push("G1 Z40", "; estimated printing time (normal mode) = 42m 10s", "; filament used [mm] = 3210.55", "; filament used [g] = 9.58");
  return out.join("\n") + "\n";
}

const dir = process.argv[2] || __dirname;
fs.writeFileSync(path.join(dir, "torus.stl"), torusStl());
fs.writeFileSync(path.join(dir, "vase.gcode"), vaseGcode());
console.log("wrote", path.join(dir, "torus.stl"), path.join(dir, "vase.gcode"));
